import "server-only";
import { Module, Unit, type Item } from "./schema.ts";
import { texToHtml } from "./tex.ts";
import type { PublicItem, PublicUnit } from "./public.ts";

import { Curriculum, isProofKu, type CurriculumUnit, type CurriculumModule } from "./curriculum.ts";
import { analysisView, orderView, proofView, workedAnalysisView } from "./public-geometry.ts";
// Content registry, generated by `npm run content:index` (a test fails when it is stale).
import { CURRICULUM, MODULE_FILES } from "./registry.generated.ts";

const MODULES = MODULE_FILES.map((f) => ({ module: Module.parse(f.module), units: f.units.map((u) => Unit.parse(u)) }));
const ROADMAP = Curriculum.parse(CURRICULUM);

/** The 52-KU roadmap (LT1, LT17, LT21), including KUs that have no content file yet. */
export function curriculum(): { units: CurriculumUnit[]; modules: CurriculumModule[]; start: string; learnBy: string } {
  return ROADMAP;
}

export function curriculumUnit(id: string): CurriculumUnit | null {
  return ROADMAP.units.find((u) => u.id === id) ?? null;
}

export type ContentModule = Module & { unitList: Unit[] };

export function listModules(): ContentModule[] {
  return MODULES.map(({ module, units }) => ({
    ...module,
    unitList: [...units].sort((a, b) => a.order - b.order),
  }));
}

export function getUnit(id: string): { unit: Unit; module: Module } | null {
  for (const { module, units } of MODULES) {
    const unit = units.find((u) => u.id === id);
    if (unit) return { unit, module };
  }
  return null;
}

export type ItemMode = "faded" | "practice" | "exit" | "review";

/** Find an item in the part of the unit that matches the mode (so exit items can't be "practised"). */
export function findItem(unit: Unit, itemId: string, mode: ItemMode): Item | null {
  const pool: Item[] =
    mode === "faded"
      ? unit.faded.steps.flatMap((s) => ("item" in s ? [s.item] : []))
      : mode === "practice"
        ? unit.practice
        : mode === "exit"
          ? unit.exit
          : unit.practice; // review: practice only, so exit-test solutions stay unseen until a retake
  return pool.find((i) => i.id === itemId) ?? null;
}

export function fadedItems(unit: Unit): Item[] {
  return unit.faded.steps.flatMap((s) => ("item" in s ? [s.item] : []));
}

/** Whitelist of what the browser sees — never answers, mistakes, solutions, sources or review links. */
export function publicItem(it: Item, opts: { hints?: boolean } = {}): PublicItem {
  return {
    id: it.id,
    type: it.type,
    level: it.level,
    promptHtml: texToHtml(it.prompt),
    optionsHtml: it.type === "mcq" ? it.options.map(texToHtml) : undefined,
    unit: it.type === "numeric" ? it.unit : undefined,
    steps: it.type === "steps" ? it.steps.map((st) => ({ promptHtml: texToHtml(st.prompt), item: publicItem(st.item) })) : undefined,
    ...(it.type === "analysis" ? analysisView(it) : {}),
    ...(it.type === "proof" ? proofView(it) : {}),
    ...(it.type === "order" ? orderView(it) : {}),
    figure: it.figure,
    drawFirst: it.drawFirst,
    hintsHtml: opts.hints && it.hints ? it.hints.map(texToHtml) : undefined,
  };
}

export function toPublicUnit(unit: Unit, module: Module): PublicUnit {
  return {
    id: unit.id,
    moduleTitle: module.title,
    title: unit.title,
    status: unit.status,
    estMinutes: unit.estMinutes,
    figure: typeof unit.figure === "string" ? unit.figure : undefined,
    figureSvg: unit.figure && typeof unit.figure !== "string" ? unit.figure : undefined,
    theoryHtml: unit.theory.map(texToHtml),
    worked: {
      problemHtml: texToHtml(unit.worked.problem),
      analysis: unit.worked.analysis ? workedAnalysisView(unit.worked.analysis) : undefined,
      steps: unit.worked.steps.map((s) => ({ html: texToHtml(s.text), whyHtml: s.why ? texToHtml(s.why) : undefined })),
      selfExplainHtml: texToHtml(unit.worked.selfExplain),
    },
    faded: {
      problemHtml: texToHtml(unit.faded.problem),
      steps: unit.faded.steps.map((s) =>
        "item" in s
          ? { kind: "blank" as const, promptHtml: texToHtml(s.prompt), item: publicItem(s.item) }
          : { kind: "text" as const, html: texToHtml(s.text) },
      ),
    },
    practice: unit.practice.map((it) => publicItem(it, { hints: true })),
    exit: unit.exit.map((it) => publicItem(it)),
    proofKu: (() => {
      const cu = curriculumUnit(unit.id);
      return !!cu && isProofKu(cu);
    })(),
  };
}
